#include <stdio.h>
#include <dirent.h>
#include <sys/stat.h>

int main(void)
{
    DIR *d;
    struct dirent *e;
    int n1 = 0, n2 = 0;

    mkdir("d", 0755);
    fclose(fopen("d/a", "w"));
    fclose(fopen("d/b", "w"));
    d = opendir("d");
    while ((e = readdir(d)) != NULL)
        if (e->d_name[0] != '.')
            n1++;
    rewinddir(d);
    while ((e = readdir(d)) != NULL)
        if (e->d_name[0] != '.')
            n2++;
    closedir(d);
    printf("%d %d\n", n1, n2);
    return 0;
}
